#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe surl-run-tests-in-parallel-without-clashes. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p shared
printf '%s\n' 'one directory, one surl' > shared/notes.txt
cat > worker.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# One test worker: its own surl on a free port over its own directory, its own tests, its own
# stop. Nothing is shared with another worker but the surl binary.
# Usage: sh worker.sh <worker number> [<password the tests log in with>]
n=$1; password=${2:-s3cret}; dir=work/$n
rm -rf "$dir" && mkdir -p "$dir/site"
printf 'worker %s\n' "$n" > "$dir/site/whoami.txt"
: > "$dir/listening.txt"
surl --directory "$dir/site" --user tester:s3cret --allow-uploads http://127.0.0.1:0/ \
  > "$dir/listening.txt" 2> "$dir/surl.log" &
pid=$!

tries=0
until grep -q '^Listening on ' "$dir/listening.txt"; do
  if ! kill -0 "$pid" 2>/dev/null; then wait "$pid"; exit; fi
  tries=$((tries + 1))
  if [ "$tries" -ge 100 ]; then kill "$pid"; exit 1; fi
  sleep 0.1
done
url=$(sed -n 's|^Listening on ||p' "$dir/listening.txt" | tr -d '\r')
echo "$url" | sed 's|.*:\([0-9]*\)/$|\1|' > "$dir/port"

# The tests: upload a result under the name every worker uses, then read it and whoami.txt back.
printf 'result of worker %s\n' "$n" > "$dir/result.txt"
get="curl -fsS --digest -u tester:$password"
$get -T "$dir/result.txt" "${url}result.txt" &&
  result=$($get "${url}result.txt") && whoami=$($get "${url}whoami.txt")
tests=$?
[ "$tests" -ne 0 ] || echo "worker $n: $whoami, $result"

kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
exit "$tests"
EOF
cat > run-parallel.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Runs <count> workers side by side, waits for all of them, prints each one's output in order,
# and exits with the first failing worker's code, or 0.
# Usage: sh run-parallel.sh <count> [<worker whose tests use a wrong password>]
count=$1; broken=${2:-0}; pids=
i=1
while [ "$i" -le "$count" ]; do
  password=s3cret; [ "$i" -ne "$broken" ] || password=wrong
  sh worker.sh "$i" "$password" > "out-$i.txt" 2>&1 &
  pids="$pids $!"
  i=$((i + 1))
done

status=0; i=1
for pid in $pids; do
  wait "$pid"; code=$?
  cat "out-$i.txt"
  if [ "$code" -ne 0 ]; then
    echo "worker $i failed: exit $code"
    [ "$status" -ne 0 ] || status=$code
  fi
  i=$((i + 1))
done
exit "$status"
EOF
cat > clash.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# What a worker meets when it shares with another: starts one surl over shared/ on a free
# port, then a second on the same directory or the same port, and exits with the second's code.
# Usage: sh clash.sh directory|port
: > first.txt
surl --directory shared http://127.0.0.1:0/ > first.txt 2> /dev/null &
first=$!
tries=0
until grep -q '^Listening on ' first.txt; do
  tries=$((tries + 1)); [ "$tries" -lt 100 ] || break; sleep 0.1
done
url=$(sed -n 's|^Listening on ||p' first.txt | tr -d '\r')
if [ "$1" = directory ]; then surl --directory shared http://127.0.0.1:0/; else surl "$url"; fi
code=$?
kill "$first"
exit "$code"
EOF
sh run-parallel.sh 4
